def strangeFunction(n):
    print(n)
    if n > 2:
        strangeFunction(n - 1)
        strangeFunction(n - 2)

def weirdFunction(nums):
    if len(nums) % 2 == 1:
        print("There are an odd amount of numbers")
    else:
        for i in range(len(nums)):
            print(i, nums[i])

