def bubbleSort(lst):
    for i in range(0, len(lst)):
        for j in range(0, len(lst) - 1):
            if lst[j] > lst[j + 1]:
                temp = lst[j]
                lst[j] = lst[j + 1]
                lst[j + 1] = temp
    return lst
